/**
 * The agent's own Slack identity. A turn's prompt carries it so the model
 * can tell which `<@U…>` mention is itself.
 */
import { callSlackApi } from "./api.js";
import { fetchSlackUserInfo, slackUserName } from "./user-info.js";
const identities = new Map();
export function resetSlackSelfIdentityCache() {
    identities.clear();
}
/** Undefined when `users.info` fails, so the caller keeps the `auth.test` handle. */
async function profileName(botToken, userId) {
    try {
        const user = await fetchSlackUserInfo({ botToken, userId });
        return user === undefined ? undefined : slackUserName(user);
    }
    catch {
        return undefined;
    }
}
/** Cached per token. A missing token or any `auth.test` failure resolves to undefined. */
export async function resolveSlackSelfIdentity(botToken) {
    if (botToken === undefined) {
        return undefined;
    }
    const cached = identities.get(botToken);
    if (cached !== undefined) {
        return cached;
    }
    try {
        const result = await callSlackApi({
            botToken,
            operation: "auth.test",
            body: {},
        });
        const userId = typeof result.user_id === "string" ? result.user_id : "";
        if (result.ok !== true || userId === "") {
            return undefined;
        }
        const handle = typeof result.user === "string" && result.user !== "" ? result.user : undefined;
        const name = (await profileName(botToken, userId)) ?? handle;
        const identity = { userId, name };
        identities.set(botToken, identity);
        return identity;
    }
    catch {
        return undefined;
    }
}
